fn json_esc(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 8);
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' | '\r' | '\t' => out.push(' '),
            c => out.push(c),
        }
    }
    out
}

pub fn lookup_cve_json(cve_id: &str) -> Option<String> {
    let needle = cve_id.trim().to_ascii_uppercase();
    let idx = KEV_CVE_TABLE.binary_search_by(|e| e.cve_id.cmp(needle.as_str())).ok()?;
    let r = &KEV_CVE_TABLE[idx];
    Some(format!(
        "{{\"cve_id\":\"{}\",\"vendor\":\"{}\",\"product\":\"{}\",\"cpe23\":\"{}\",\"cvss\":{}.{},\"severity\":\"{}\",\"cwe\":\"{}\",\"is_kev\":{},\"ransomware_use\":\"{}\",\"epss\":{:.3},\"summary\":\"{}\",\"remediation\":\"{}\",\"spdx_license\":\"US-Gov-Public-Domain\"}}",
        json_esc(r.cve_id), json_esc(r.vendor), json_esc(r.product), json_esc(r.cpe23),
        r.cvss_x10 / 10, r.cvss_x10 % 10, json_esc(r.severity), json_esc(r.cwe),
        if r.is_kev { "true" } else { "false" }, json_esc(r.ransomware),
        (r.epss_permille as f64) / 1000.0, json_esc(r.summary), json_esc(r.remediation)
    ))
}
